INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
1026, '数学', '三年级', '应用题', 2, '{"stem": "学校举行船模比赛，小华和小海及其他22个学生参加，平均分成2组，每组有多少个学生？", "options": null}', '12个', '参加比赛的一共有1+1+22=24（人），平均分成2组：24÷2=12（人）。答：每组有12个学生。', 'paper', '["practice", "ykl3sx", "4.6"]', '["paper_png/ykl3_sx/p078.png"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
1027, '数学', '三年级', '应用题', 2, '{"stem": "88个乒乓球，每袋装5个，可以装多少袋？还剩多少个？", "options": null}', '17袋；还剩3个', '88÷5=17……3（5×17=85，88-85=3）。答：可以装17袋，还剩3个。', 'paper', '["practice", "ykl3sx", "4.6"]', '["paper_png/ykl3_sx/p079.png"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
1026, '数学', '三年级', '应用题', 2, '{"stem": "欢欢等4个小伙伴折了98个千纸鹤，如果把千纸鹤7个穿成一串，可以穿多少串？", "options": null}', '14串', '98÷7=14（想7的乘法口诀：7×14=98）。答：可以穿14串。', 'paper', '["practice", "ykl3sx", "4.6"]', '["paper_png/ykl3_sx/p079.png"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
1026, '数学', '三年级', '应用题', 3, '{"stem": "一共有4个篮子，每个篮子里有14个桃，还多了7个，一共有多少个桃？把这些桃平均分给3只小猴，每只小猴分到多少个桃？", "options": null}', '63个；21个', '先算篮子里的桃：4×14=56（个），加上多出的：56+7=63（个）；再平均分给3只小猴：63÷3=21（个）。答：一共有63个桃，每只小猴分到21个。', 'paper', '["practice", "ykl3sx", "4.6"]', '["paper_png/ykl3_sx/p079.png"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
1027, '数学', '三年级', '填空', 3, '{"stem": "□6÷5，要使商是一位数，□里最大填（　）；要使商是两位数，□里最小填（　）。", "options": null}', '4；5', '□6÷5：如果□6比50小，商是一位数（如46÷5=9……1），□最大填4；如果□6不小于50，商是两位数（如56÷5=11……1），□最小填5。', 'paper', '["practice", "ykl3sx", "4.6"]', '["paper_png/ykl3_sx/p079.png"]', 0);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
1027, '数学', '三年级', '填空', 3, '{"stem": "李老师拿来一些橡皮作比赛的奖品，平均分给6名获奖的学生，一直分到不能分为止。巧的是，每人分到几块橡皮，就余下几块橡皮。你知道李老师一共拿来多少块橡皮吗？（你能想到几个答案就写几个）", "options": null}', '7、14、21、28、35', '设每人分到q块，则余下也是q块，且余数q必须比除数6小，q可取1、2、3、4、5。橡皮总数=6×q+q=7q，所以是7、14、21、28、35块。', 'paper', '["practice", "ykl3sx", "4.6"]', '["paper_png/ykl3_sx/p079.png"]', 0);
